create table public."tblMonthlySales" (
  "ID" bigint generated by default as identity not null,
  "BOH" integer null,
  "Cash" integer null,
  "GCash" integer null,
  "Grab" numeric null,
  "DateAdded" timestamp with time zone null default now(),
  "DateUpdated" timestamp with time zone null default now(),
  "CreatedBy" uuid null,
  constraint tblmonthlysales_pkey primary key ("ID"),
  constraint tblmonthlysales_createdby_fkey foreign KEY ("CreatedBy") references auth.users (id) on delete CASCADE
) TABLESPACE pg_default;


ALTER TABLE "tblMonthlySales"
ENABLE ROW LEVEL SECURITY;


-- Policy: Users can view all product

CREATE POLICY "User can view all product"

ON "tblMonthlySales"

FOR SELECT

USING (true);


-- Policy: Users can create product

CREATE POLICY "User can create Product"

ON "tblMonthlySales"

FOR INSERT

WITH CHECK (auth.uid() = "CreatedBy");


-- Policy: User can update Product
-- that they created or assigned

CREATE POLICY "User can update Product that they created or assigned"

ON "tblMonthlySales"

FOR UPDATE

USING (
    auth.uid() = "CreatedBy"
)

WITH CHECK (
    auth.uid() = "CreatedBy"
);


-- Policy: Only creators can delete Product

CREATE POLICY "Only creators can delete Product"

ON "tblMonthlySales"

FOR DELETE

USING (auth.uid() = "CreatedBy");


-- Function to update timestamp

CREATE OR REPLACE FUNCTION update_DateAdded()

RETURNS TRIGGER AS $$

BEGIN

    NEW."DateUpdated" = NOW();

    RETURN NEW;

END;

$$ LANGUAGE plpgsql;


-- Trigger

CREATE TRIGGER update_tblMonthlySales_DateAdded

BEFORE UPDATE ON "tblMonthlySales"

FOR EACH ROW

EXECUTE FUNCTION update_DateAdded();